begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();sa uuid;sb uuid;g uuid;pid uuid:=gen_random_uuid();did uuid:=gen_random_uuid();cid uuid;file uuid;second uuid;r jsonb;f jsonb;failed boolean;i int;
begin
 insert into auth.users(id,email_confirmed_at) values(a,now()),(b,now());
 sa:=public.memocious_session_open(repeat('1',64),repeat('2',64),a,'customer','fixture','1');sb:=public.memocious_session_open(repeat('3',64),repeat('4',64),b,'customer','fixture','1');g:=public.memocious_session_open(repeat('5',64),repeat('6',64),null,'guest',null,'1');
 select id into cid from memocious.categories where slug='gift-hampers';
 insert into memocious.products(id,slug,name,active,publication_state,customizable,price_paise) values(pid,'file-fixture','Private file fixture',true,'published',true,0);
 insert into memocious.product_categories(product_id,category_id) values(pid,cid);
 insert into memocious.product_images(product_id,public_path,alt,sanitized_at,published_at) values(pid,'/media/file-fixture.webp','Fixture',now(),now());perform memocious_private.refresh_publication();
 f:=jsonb_build_object('budgetMinPaise',0,'budgetMaxPaise',10000,'giftTypeId',cid,'occasionId',null,'recipient','','message','','productId',pid,'pricingVersion',1,'options','[]'::jsonb,'quantity',1,'requestedDate',((now() at time zone 'Asia/Kolkata')::date+10)::text,'contact',jsonb_build_object('name','Test','phone','447700900123','email','','city','Test','pincode','400001'));
 execute 'set local role service_role';perform public.memocious_builder_draft(sa,'create',did,0,2,6,f);
 failed:=false;begin perform public.memocious_builder_file_begin(sb,did,1,100,'image/png');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Cross-user reservation';end if;
 failed:=false;begin perform public.memocious_builder_file_begin(g,did,1,100,'image/png');exception when invalid_authorization_specification then failed:=true;end;if not failed then raise exception 'Guest reservation';end if;
 failed:=false;begin perform public.memocious_builder_file_begin(sa,did,1,2097153,'image/png');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Oversize reservation';end if;
 failed:=false;begin perform public.memocious_builder_file_begin(sa,did,1,100,'image/svg+xml');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Active type reservation';end if;
 file:=public.memocious_builder_file_begin(sa,did,1,100,'image/png');
 failed:=false;begin perform public.memocious_builder_file(sb,file,'claim');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Cross-user claim';end if;
 failed:=false;begin perform public.memocious_builder_file(sa,file,'read');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Quarantine readable';end if;
 r:=public.memocious_builder_file(sa,file,'claim');if r->>'path'<>'builder/'||file||'.webp' or r->>'quarantine'<>'builder/'||file then raise exception 'Path not exact';end if;
 failed:=false;begin perform public.memocious_builder_file(sa,file,'claim');exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Ticket reuse';end if;
 failed:=false;begin perform public.memocious_builder_file(sa,file,'ready','{"width":2049,"height":1,"bytes":100,"digest":"bad"}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Invalid normalized output';end if;
 r:=public.memocious_builder_file(sa,file,'ready',jsonb_build_object('width',100,'height',100,'bytes',100,'digest',repeat('a',64)));
 if r->>'version'<>'2' or public.memocious_builder_draft(sa,'read',did)->'files'->0->>'status'<>'ready_private' then raise exception 'Ready attachment/version';end if;
 perform public.memocious_builder_file(sa,file,'ready',jsonb_build_object('width',100,'height',100,'bytes',100,'digest',repeat('a',64)));
 if public.memocious_builder_draft(sa,'read',did)->>'version'<>'2' then raise exception 'Ready replay bumped version';end if;
 failed:=false;begin perform public.memocious_builder_file(sb,file,'read');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Cross-user private read';end if;
 failed:=false;begin perform public.memocious_builder_file(sa,file,'publish');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Builder photo publication';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,2,2,1,jsonb_set(f,'{productId}','null'));exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Orphaned incompatible files';end if;
 second:=public.memocious_builder_file_begin(sa,did,2,100,'image/png');perform public.memocious_builder_file(sa,second,'claim');perform public.memocious_builder_draft(sa,'save',did,2,2,6,jsonb_set(f,'{message}','"Changed"'));
 failed:=false;begin perform public.memocious_builder_file(sa,second,'ready',jsonb_build_object('width',1,'height',1,'bytes',100,'digest',repeat('b',64)));exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Stale-parent file attached';end if;perform public.memocious_builder_file(sa,second,'reject');
 for i in 1..4 loop perform public.memocious_builder_file_begin(sa,did,3,100,'image/png');end loop;
 failed:=false;begin perform public.memocious_builder_file_begin(sa,did,3,100,'image/png');exception when program_limit_exceeded then failed:=true;end;if not failed then raise exception 'Five-file reservation quota';end if;
 perform public.memocious_builder_file(sa,file,'remove','{"version":3}');
 failed:=false;begin perform public.memocious_builder_file(sa,file,'read');exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Removed file readable';end if;
 perform public.memocious_builder_draft(sa,'delete',did,4);
 failed:=false;begin perform public.memocious_builder_draft(sa,'read',did);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Deleted draft readable';end if;
 execute 'reset role';update memocious.request_uploads set updated_at=now()-interval '2 days' where draft_id=did;execute 'set local role service_role';
 r:=public.memocious_builder_file_cleanup();if jsonb_array_length(r)<>6 then raise exception 'Cleanup paths missing';end if;
 for file in select id from memocious.request_uploads where draft_id=did loop perform public.memocious_builder_file_cleanup(file,true,false);end loop;
 if public.memocious_builder_cleanup()->>'processed'<>'1' then raise exception 'Reconciled draft not deleted';end if;
 execute 'reset role';
end $$;
rollback;
select 'PASS: private builder file ownership, reservation size/type/quota, exact ticket path/reuse, quarantine denial, normalized-output bounds, ready replay, parent conflicts, no publish action, removal revocation, draft cancellation and reconciled cleanup' as result;
